WITH base AS (SELECT id, customer_id, device, browser, started_at, country, INITCAP(TRIM(browser)) AS browser_title FROM sessions WHERE started_at > TIMESTAMP '2023-04-24 21:00:00' AND country IS NOT NULL AND customer_id IS NULL) SELECT device, COUNT_IF(browser = 'Safari') AS safari_events, COUNT(*) AS cnt, COUNT_IF(device = 'desktop') AS desktop_events, COUNT(*) AS num_rows, (UNIX_TIMESTAMP(MAX(started_at)) - UNIX_TIMESTAMP(MIN(started_at))) / 60 AS duration_min, MAX(started_at) AS last_started_at FROM base GROUP BY device;
